package main
import("crypto/ecdsa";"crypto/elliptic";"crypto/rand";"crypto/x509";"crypto/x509/pkix";"encoding/pem";"math/big";"os";"time")
func main(){ k,_:=ecdsa.GenerateKey(elliptic.P256(),rand.Reader); c:=&x509.Certificate{SerialNumber:big.NewInt(1),Subject:pkix.Name{CommonName:"spike CA"},NotBefore:time.Now().Add(-time.Hour),NotAfter:time.Now().Add(24*time.Hour),IsCA:true,BasicConstraintsValid:true,KeyUsage:x509.KeyUsageCertSign}; der,e:=x509.CreateCertificate(rand.Reader,c,c,&k.PublicKey,k);if e!=nil{panic(e)};os.WriteFile("ca.pem",pem.EncodeToMemory(&pem.Block{Type:"CERTIFICATE",Bytes:der}),0600); leaf,_:=ecdsa.GenerateKey(elliptic.P256(),rand.Reader); t:=&x509.Certificate{SerialNumber:big.NewInt(2),Subject:pkix.Name{CommonName:"adapter.spike.test"},DNSNames:[]string{"adapter.spike.test"},NotBefore:time.Now().Add(-time.Hour),NotAfter:time.Now().Add(24*time.Hour),KeyUsage:x509.KeyUsageDigitalSignature,ExtKeyUsage:[]x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},BasicConstraintsValid:true};der,e=x509.CreateCertificate(rand.Reader,t,c,&leaf.PublicKey,k);if e!=nil{panic(e)};os.WriteFile("server.pem",pem.EncodeToMemory(&pem.Block{Type:"CERTIFICATE",Bytes:der}),0600); for _,variant:=range []string{"client-only","expired"}{ if variant=="client-only"{t.ExtKeyUsage=[]x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}}else{t.ExtKeyUsage=[]x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth};t.NotBefore=time.Now().Add(-48*time.Hour);t.NotAfter=time.Now().Add(-24*time.Hour)};v,e:=x509.CreateCertificate(rand.Reader,t,c,&leaf.PublicKey,k);if e!=nil{panic(e)};os.WriteFile(variant+".pem",pem.EncodeToMemory(&pem.Block{Type:"CERTIFICATE",Bytes:v}),0600)};key,_:=x509.MarshalECPrivateKey(leaf);os.WriteFile("server-key.pem",pem.EncodeToMemory(&pem.Block{Type:"EC PRIVATE KEY",Bytes:key}),0600)}
